const metadata = "Bibliographic metadata";
const bookLimit = "Only bibliographic metadata and the displayed publisher/library description were checked. Chapters, historical case selections and supporting analyses remain unread; this source supplies provenance, not empirical support for universal institutional mechanisms.";
function book(id, title, authors, year, url, note = "") {
  publication({ id, title, authors, year, url, extent: "publisher-or-institution-bibliographic-metadata-only", locators: [metadata], limit: `${bookLimit}${note ? ` ${note}` : ""}` });
}
function bib(sourceId, disposition = "metadata-only", reason = bookLimit, locator = metadata) {
  return { sourceId, locator, disposition, reason };
}
function evidence(...ids) { return ids.map((id) => ({ nodeId: `soc:${id}`, claimIds: [`${id.startsWith("un-charter") || id === "dispersed-knowledge-argument" ? "D" : "C"}-soc-${id}`] })); }

