publication({ id: "ostrom1992-covenants", title: "Covenants with and without a Sword: Self-Governance Is Possible", authors: ["Elinor Ostrom", "James Walker", "Roy Gardner"], year: 1992,
  doi: "10.2307/1964229", url: "https://www.cambridge.org/core/journals/american-political-science-review/article/covenants-with-and-without-a-sword-selfgovernance-is-possible/2191864CCB589D4B3528090CB596C254", journal: "American Political Science Review", volume: "86", issue: "2", pages: "404-417",
  extent: "selected-final-published-methods-and-institutional-results", locators: ["Final article pp. 407-410: subjects, baseline, one-shot and repeated communication", "Final article pp. 410-411: imposed sanctioning, monitoring, fees and fines", "Final article pp. 411-412: imposed communication and sanctioning; three group trajectories", "Final article pp. 412-413: endogenous sanctioning choice, prior experience and initial communication"],
  limit: "Publisher metadata and selected Methods/Results of the final 1992 article were read from the published scan at https://www.wtf.tw/ref/ostrom_1992.pdf, with local OCR assistance. The distinct 1991 conference paper is not substituted. Tables, individual decisions, transcript coding and equilibrium derivations were not independently replayed. Experienced Indiana undergraduates, sequential stages, endowment differences and prior-institution experience constrain inference; the related designs are not independent field replications. CPR yield before sanction costs differs from take-home yield after fees/fines. No universal institutional effect size or population-scale governance mechanism is admitted." });
study({ id: "ostrom1992-communication-designs", sourceId: "ostrom1992-covenants", system: "Eight-person Indiana undergraduate CPR groups with prior common-pool decision experience; low- and high-token endowments",
  locators: ["Final article pp. 407-410: subjects, baseline, one-shot and repeated communication"],
  preparation: "Subjects privately allocate integer tokens between a fixed-return market and a group-dependent CPR, receiving cash earnings. After an initial block without communication, the high-endowment one-shot design permits one ten-minute discussion; distinct repeated-communication designs permit discussion after subsequent rounds in low- and high-endowment environments. Individual investments remain anonymous and only aggregate investments reveal defections.",
  observable: "CPR yield relative to the designed joint optimum, verbal agreements and departures from agreed investments over subsequent rounds", finding: "Communication phases show improved reported group yields, but the one-shot improvement decays and repeated communication performs less well in the higher-endowment setting. Some groups sustain mutually agreed strategies without an externally imposed participant-enforcement authority.",
  limitations: ["Before/after blocks share participants and a fixed phase order; learning, time and communication are not independently randomized in this reading. Different endowment designs must not be pooled into one universal effect.", "No communication treatment means no formal discussion, not an absence of all experimenter rules. Verbal reproach, researcher-administered payments and internal agreements remain institutional conditions."] });
observation({ id: "covenants-external-enforcer-boundary", name: "Communication-dependent agreements with bounded durability", studyId: "ostrom1992-communication-designs", statement: "The final article reports improved CPR yields and agreements during communication phases without an external participant-enforcement authority. One-shot gains decay; repeated-discussion results depend on endowment and retain verbal reproach. This establishes a bounded possibility, not guaranteed governance or absence of every enforcement mechanism." });
study({ id: "ostrom1992-sanction-only", sourceId: "ostrom1992-covenants", system: "Eight high-endowment CPR experiments with costly peer fines and no group discussion",
  locators: ["Final article pp. 407-410: subjects, baseline, one-shot and repeated communication", "Final article pp. 410-411: imposed sanctioning, monitoring, fees and fines"],
  preparation: "Unlike the anonymous-investment communication design, individual decisions are displayed under subject numbers throughout. After ten initial rounds introduce a costly option to fine another participant, varying fee/fine schedules across experiments; experimenters privately account for fees and fines.",
  observable: "Investments, CPR yield before sanction costs, earnings after fees/fines, and costly sanction events", finding: "The source reports improved CPR yield after sanctions become available, but fees and fines consume much of that gain. Some fines target earlier rather than immediate overinvestment, low investors or cases not explained by the authors' classification.",
  limitations: ["Individual monitoring is bundled into this design; comparison with anonymous designs does not isolate sanction availability alone. Fee/fine variants and prior experience are not interchangeable.", "The authors' revenge/error categories draw on interviews and observations, not independently manipulated motives. Positive pre-cost resource yield does not prove improved final welfare."] });
observation({ id: "sanction-cost-accounting", name: "Costly fines change the apparent cooperation payoff", studyId: "ostrom1992-sanction-only", statement: "The final article's sanction-only designs distinguish higher CPR yield from earnings after fees and fines; costly and misdirected sanctions substantially reduce the apparent gain. Monitoring, sanction availability, sanction targeting and cost accounting are separate features, not a universally effective enforcement mechanism." });
study({ id: "ostrom1992-imposed-combination", sourceId: "ostrom1992-covenants", system: "Three high-endowment CPR experiments with imposed discussion and a peer-fine option",
  locators: ["Final article pp. 407-410: subjects, baseline, one-shot and repeated communication", "Final article pp. 411-412: imposed communication and sanctioning; three group trajectories"],
  preparation: "After ten initial rounds, impose one ten-minute discussion and the opportunity to fine peers. Retain each group's stated strategy, subsequent investments and sanction costs as distinct trajectories.",
  observable: "Agreements, subsequent defections, use of fines and earnings before/after sanction costs", finding: "One group agrees on a near-optimal strategy and sustains sixteen subsequent rounds without defection or use of fines; another agrees on a less efficient strategy and uses occasional sanctions; a third fails to form a clear strategy and incurs substantial fine costs.",
  limitations: ["The same nominal institutional combination produces different trajectories. The unused threat in one successful group does not identify whether communication or sanction availability caused compliance.", "Three groups do not establish necessity, a universal synergy coefficient or independence from the initially learned history."] });
observation({ id: "combined-institution-trajectories", name: "Jointly available rules do not guarantee successful organization", studyId: "ostrom1992-imposed-combination", statement: "Three groups with discussion and fines show different strategy, compliance and cost outcomes. One maintains its agreement without exercising fines, while a group without a clear agreement spends heavily on them. Nominal availability of the same components does not guarantee equivalent whole-group performance." });
study({ id: "ostrom1992-endogenous-selection", sourceId: "ostrom1992-covenants", system: "Previously sanction-experienced CPR participants choosing a fine institution; four delayed-choice and two initial-choice groups",
  locators: ["Final article pp. 412-413: endogenous sanctioning choice, prior experience and initial communication"],
  preparation: "Recruit from the prior imposed-sanction pool. In four experiments permit discussion and majority choice of a sanction mechanism after an initial block; in two additional experiments provide that opportunity at the outset. Track choices, prior fee/fine experience and later yields separately.",
  observable: "Institution adoption, prior treatment experience, agreement compliance and group yield net of sanction costs", finding: "Selected groups adopting sanctions often attain high yields, while the delayed-choice groups rejecting them show different subsequent declines. Voting also differs with participants' previous sanction experience; choosing and rejecting groups are not randomized versions of the same institution.",
  limitations: ["Endogenous adoption, prior-experiment carryover and timing selection preclude interpreting the adopter/nonadopter contrast as an isolated causal effect of sanctions.", "The two initial-choice groups test a different timing preparation and do not independently establish an optimal universal governance constructor."] });
observation({ id: "institution-choice-history", name: "Institution choice is entangled with prior experience and selection", studyId: "ostrom1992-endogenous-selection", statement: "The source's voluntarily chosen sanction institutions coexist with high reported yields in selected groups, but adoption correlates with prior institutional experience and differs by timing. This is evidence for historical and selection boundaries, not a randomized theorem that chosen sanctions cause cooperation." });

